export const monologueLines: Line[] = [
  {"id":"L001","speaker":"dev","text":"Okay, this is a recording for the team, explaining how I'm thinking about the sync engine for the upload queue.","start":2,"end":9.2},
  {"id":"L002","speaker":"dev","text":"The goal is simple to say and hard to build. A technician should never lose work, no matter what the network does.","start":9.4,"end":17.7},
  {"id":"L003","speaker":"dev","text":"Today, the app sends every change straight to the server. If the request fails, the change is just gone.","start":18,"end":24.8},
  {"id":"L004","speaker":"dev","text":"So the first principle is that every change gets written to the device first, and only then sent to the server.","start":25,"end":32.8},
  {"id":"L005","speaker":"dev","text":"On Android, the local store is SQL light. On iOS it's also SQL light, through a thin wrapper.","start":33,"end":39.6},
  {"id":"L006","speaker":"dev","text":"The second principle is that every change gets a unique ID, generated on the device.","start":39.8,"end":45.5},
  {"id":"L007","speaker":"dev","text":"That means if we send the same change twice, which will happen on flaky networks, the server can recognize the duplicate and ignore it.","start":45.7,"end":54.6},
  {"id":"L008","speaker":"dev","text":"In other words, every write has to be idem potent. That's non-negotiable.","start":54.8,"end":59.4},
  {"id":"L009","speaker":"dev","text":"Okay, conflicts. This is where it gets interesting.","start":61.6,"end":64.5},
  {"id":"L010","speaker":"dev","text":"A conflict happens when two devices change the same field before either one has synced.","start":64.8,"end":70.2},
  {"id":"L011","speaker":"dev","text":"There are basically three ways to handle it.","start":70.4,"end":73.6},
  {"id":"L012","speaker":"dev","text":"One, last-write-wins. Whichever change has the latest timestamp wins, and the other is discarded.","start":73.8,"end":78.8},
  {"id":"L013","speaker":"dev","text":"Two, you use vector clucks to detect that two changes were concurrent, and then ask a human to resolve it.","start":79.1,"end":86.2},
  {"id":"L014","speaker":"dev","text":"Three, you use see are DTs, data structures that merge automatically without conflicts.","start":86.4,"end":91.1},
  {"id":"L015","speaker":"dev","text":"See are DTs are beautiful, but they're a big investment, and they make every feature harder to build afterwards.","start":91.3,"end":99},
  {"id":"L016","speaker":"dev","text":"For version one, I'm proposing last-write-wins, plus a conflict log.","start":99.2,"end":103.2},
  {"id":"L017","speaker":"dev","text":"The server keeps the losing change, so the office can see what was overwritten, and restore it if needed.","start":103.4,"end":111},
  {"id":"L018","speaker":"dev","text":"Research says conflicts are rare, so this is the right trade-off for now.","start":111.3,"end":116.5},
  {"id":"L019","speaker":"dev","text":"One risk with last-write-wins is clock skew. Device clocks can be wrong by minutes.","start":116.7,"end":122},
  {"id":"L020","speaker":"dev","text":"So we'll use the server's receive time, not the device time, to decide the winner.","start":122.2,"end":128.1},
  {"id":"L021","speaker":"dev","text":"Last part, photos. Photos are different because they're big.","start":130.4,"end":133.9},
  {"id":"L022","speaker":"dev","text":"A job can have fifteen photos at five megabytes each. On a weak connection, that's minutes of uploading.","start":134.2,"end":140.8},
  {"id":"L023","speaker":"dev","text":"So photos get their own queue, separate from the form data. The form syncs first, because it's small and the office needs it.","start":141,"end":150.1},
  {"id":"L024","speaker":"dev","text":"Photos upload in the background, one at a time, with resumable uploads, so a dropped connection doesn't restart from zero.","start":150.4,"end":157.7},
  {"id":"L025","speaker":"dev","text":"And we back off exponentially when uploads fail, so we don't drain the battery retrying every second.","start":158,"end":164.5},
  {"id":"L026","speaker":"dev","text":"Open question I don't have an answer to yet: what happens if the device is wiped before the queue drains?","start":164.7,"end":172},
  {"id":"L027","speaker":"dev","text":"Some medical customers wipe tablets every night. If that happens, queued work is lost, which is exactly what we're trying to prevent.","start":172.3,"end":181.2},
  {"id":"L028","speaker":"dev","text":"I need numbers on how many customers do that before I can design around it.","start":181.5,"end":187.3},
  {"id":"L029","speaker":"dev","text":"Okay, that's it. Questions in the doc comments, please. Thanks.","start":187.6,"end":191.3},
];
